    if (file == null) {
        throw new NullPointerException("The file must not be null");
    }
    try {
        if (file.isDirectory()) {
            deleteDirectoryOnExit(file);
        } else {
            file.deleteOnExit();
        }
    } catch (Exception e) {
        throw new IOException("Deletion of file on exit was unsuccessful", e);
    }
}

private static void deleteDirectoryOnExit(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }
    File[] files = directory.listFiles();
    if (files != null) {
        for (File file : files) {
            if (file.isDirectory()) {
                deleteDirectoryOnExit(file);
            } else {
                file.deleteOnExit();
            }
        }
    }
    directory.deleteOnExit();
}

