        List<V> set1 = new ArrayList<>();
        List<V> set2 = new ArrayList<>();

        // Splitting the resultMap values into two sets for bipartition
        boolean addToSet1 = true;
        for (V vertex : resultMap.values()) {
            if (addToSet1) {
                set1.add(vertex);
            } else {
                set2.add(vertex);
            }
            addToSet1 = !addToSet1;
        }

        // Adding vertices to the graph
        for (V vertex : resultMap.values()) {
            target.addVertex(vertex);
        }

        // Adding edges to form a complete bipartite graph
        for (V v1 : set1) {
            for (V v2 : set2) {
