@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Graph and resultMap cannot be null");
    }

    // Assuming resultMap contains vertices to be added to the bipartite graph
    Collection<V> vertices = resultMap.values();
    if (vertices.size() < 2) {
        throw new IllegalArgumentException("At least two vertices are required to form a bipartite graph");
    }

    // Split vertices into two sets for bipartite graph
    List<V> set1 = new ArrayList<>();
    List<V> set2 = new ArrayList<>();
    Iterator<V> iterator = vertices.iterator();

    // Distribute vertices into two sets
    while (iterator.hasNext()) {
        set1.add(iterator.next());
        if (iterator.hasNext()) {
            set2.add(iterator.next());
        }
    }

    // Add vertices to the graph
    target.addAllVertices(set1);
    target.addAllVertices(set2);

    // Add edges between vertices of set1 and set2
    for (V vertex1 : set1) {
        for (V vertex2 : set2) {
            target.addEdge(vertex1, vertex2);
        }
    }
}

