    List<V> set1Vertices = new ArrayList<>();
    List<V> set2Vertices = new ArrayList<>();

    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        if (entry.getKey().equals("set1")) {
            set1Vertices.add(entry.getValue());
        } else if (entry.getKey().equals("set2")) {
            set2Vertices.add(entry.getValue());
        }
    }

    // Add edges between every vertex in set1 and every vertex in set2
    for (V vertex1 : set1Vertices) {
        for (V vertex2 : set2Vertices) {
            target.addEdge(vertex1, vertex2);
        }
    }
}

