public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        // Calculate the size of the message
        int size = schema.getSerializedSize(message, buffer);

        // Write the size of the message as a varint
        ProtobufOutput output = new ProtobufLinkedBufferOutput(buffer);
        output.writeRawVarint32(size);

        // Write the message
        schema.writeTo(output, message);

        // Flush the buffer to the output stream
        out.write(buffer.buffer, 0, buffer.position);

        // Return the total bytes written (size of message in bytes + size of varint length prefix)
        return buffer.position;
    } finally {
        // Reset the buffer's position for reuse
        buffer(position = 0);
    }
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    final byte[] data;
    try {
        data = schema.writeTo(buffer, message);
    } finally {
        buffer.clear();
    }

    final int size = data.length;
    writeVarInt32(out, size); // Write the size of the message
    out.write(data); // Write the actual message
    return size;
}

private static void writeVarInt32(OutputStream out, int value) throws IOException {
    while (true) {
        if ((value & ~0x7F) == 0) {
            out.write(value);
            return;
        } else {
            out.write((value & 0x7F) | 0x80);
            value >>>= 7;
        }
    }
}

