public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    final byte[] data;
    try {
        data = schema.writeTo(buffer, message).toByteArray();
    } catch (Exception e) {
        throw new IOException("Error serializing message", e);
    }

    int size = data.length;
    out.write((size >>> 0) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 24) & 0xFF);
    out.write(data);

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    // Serialize the message into the buffer
    final byte[] data;
    try {
        data = schema.writeTo(buffer, message);
    } finally {
        buffer.clear();
    }

    // Write the size of the message as a varint
    int size = data.length;
    out.write(CodedOutputStream.computeRawVarint32Size(size));
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    cos.flush();

    // Write the message data
    out.write(data);

    return data.length;
}

