public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }

    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] result = new Class<?>[actualTypeArguments.length];

        for (int i = 0; i < actualTypeArguments.length; i++) {
            if (actualTypeArguments[i] instanceof Class) {
                result[i] = (Class<?>) actualTypeArguments[i];
            } else {
                return null; // Cannot resolve the type arguments
            }
        }

        return result;
    }

    return null; // Not a parameterized type
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType paramType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = paramType.getActualTypeArguments();
        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            if (actualTypeArguments[i] instanceof Class) {
                resolvedArguments[i] = (Class<?>) actualTypeArguments[i];
            } else if (actualTypeArguments[i] instanceof TypeVariable) {
                TypeVariable<?> typeVariable = (TypeVariable<?>) actualTypeArguments[i];
                resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
            } else {
                return null; // cannot resolve
            }
        }
        return resolvedArguments;
    }
    return null; // not parameterized
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Class<?> rawType = targetType;
    do {
        for (Type genericInterface : rawType.getGenericInterfaces()) {
            if (genericInterface instanceof ParameterizedType) {
                ParameterizedType parameterizedInterface = (ParameterizedType) genericInterface;
                Type[] actualTypeArguments = parameterizedInterface.getActualTypeArguments();
                TypeVariable<?>[] typeVariables = ((Class<?>) parameterizedInterface.getRawType()).getTypeParameters();
                for (int i = 0; i < typeVariables.length; i++) {
                    if (typeVariable.equals(typeVariables[i])) {
                        return (Class<?>) actualTypeArguments[i];
                    }
                }
            }
        }
        Type genericSuperclass = rawType.getGenericSuperclass();
        if (genericSuperclass instanceof ParameterizedType) {
            ParameterizedType parameterizedSuperclass = (ParameterizedType) genericSuperclass;
            Type[] actualTypeArguments = parameterizedSuperclass.getActualTypeArguments();
            TypeVariable<?>[] typeVariables = rawType.getSuperclass().getTypeParameters();
            for (int i = 0; i < typeVariables.length; i++) {
                if (typeVariable.equals(typeVariables[i])) {
                    return (Class<?>) actualTypeArguments[i];
                }
            }
        }
        rawType = rawType.getSuperclass();
    } while (rawType != null);
    return null; // cannot resolve
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || !(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

    if (actualTypeArguments == null || actualTypeArguments.length == 0) {
        return null;
    }

    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type arg = actualTypeArguments[i];
        if (arg instanceof Class) {
            resolvedArguments[i] = (Class<?>) arg;
        } else if (arg instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) arg;
            resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
        } else {
            return null; // Cannot resolve other types of arguments
        }
    }

    return resolvedArguments;
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Type genericSuperclass = targetType.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
