public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length specified");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        int codepoint = Character.codePointAt(str, i);
        if (codepoint == 0) {
            size += 1;
        } else if (codepoint <= 0x7F) {
            size += 1;
        } else if (codepoint <= 0x7FF) {
            size += 2;
        } else if (codepoint <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
            i++; // Skip the second surrogate
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Index and length must be within the bounds of the string");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            // Check for surrogate pairs
            if (i + 1 < index + len && Character.isSurrogatePair(ch, str.charAt(i + 1))) {
                size += 4; // Surrogate pair takes 4 bytes in UTF-8
                i++; // Move to the next character as it's part of the surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid surrogate character without a pair");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("CharSequence must not be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index and length must be within the bounds of the CharSequence");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            // Handle surrogate pairs
            if (i + 1 >= index + len) {
                throw new IllegalArgumentException("Invalid surrogate pair at index " + i);
            }
            char nextCh = str.charAt(i + 1);
            if (Character.toCodePoint(ch, nextCh) > 0xFFFF) {
                size += 4; // 4 bytes for supplementary characters
                i++; // Skip the next char as it is part of the surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair at index " + i);
            }
        } else {
            size += 3;
        }
    }

    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Index and length must be non-negative and index + length must be less than or equal to the length of the string");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else if (Character.isSurrogate(c)) {
            // Check for surrogate pairs
            if (i + 1 < index + len) {
                char nextC = str.charAt(i + 1);
                if (Character.isSurrogatePair(c, nextC)) {
                    size += 4; // surrogate pair
                    i++; // skip the next character as it is part of the surrogate pair
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair in the string");
                }
            } else {
                throw new IllegalArgumentException("Truncated surrogate pair at the end of the string");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("CharSequence str cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length specified");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 >= index + len) {
                throw new IllegalArgumentException("Unpaired high surrogate");
            }
            char nextChar = str.charAt(i + 1);
            if (Character.isLowSurrogate(nextChar)) {
                size += 4;
                i++; // Skip the low surrogate as it's already counted
            } else {
                throw new IllegalArgumentException("Unpaired high surrogate");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

