public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Arguments str, session, and lb cannot be null");
    }

    int length = str.length();
    int utf8Length = 0;
    for (int i = 0; i < length; i++) {
        utf8Length += encodeChar(str.charAt(i), new byte[0]);
    }

    byte[] buffer = lb.buffer;
    int bufferCapacity = buffer.length;
    int offset = lb.offset;

    if (offset + utf8Length > bufferCapacity) {
        lb = lb.next = LinkedBuffer.allocate(session.nextBufferSize(bufferCapacity), lb);
        buffer = lb.buffer;
        offset = lb.offset;
    }

    for (int i = 0; i < length; i++) {
        offset = encodeChar(str.charAt(i), buffer, offset);
    }

    lb.offset = offset;
    return lb;
}

private static int encodeChar(char c, byte[] buffer, int offset) {
    if (c < 0x80) {
        buffer[offset++] = (byte) c;
    } else if (c < 0x800) {
        buffer[offset++] = (byte) (0xC0 | (c >> 6));
        buffer[offset++] = (byte) (0x80 | (c & 0x3F));
    } else if (c < 0xD800 || c >= 0xE000) {
        buffer[offset++] = (byte) (0xE0 | (c >> 12));
        buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3F));
        buffer[offset++] = (byte) (0x80 | (c & 0x3F));
    } else { // surrogates
        if (i + 1 >= length) throw new IllegalArgumentException("unpaired surrogate");

        char d = str.charAt(++i);
        if (c < 0xDC00 || c >= 0xDE00 || d < 0xDC00 || d >= 0xE000) {
            throw new IllegalArgumentException("unpaired surrogate");
        }

        int codePoint = 0x10000 + (((c & 0x3FF) << 10) | (d & 0x3FF));
        buffer[offset++] = (byte) (0xF0 | (codePoint >> 18));
        buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
        buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
        buffer[offset++] = (byte) (0x80 | (codePoint & 0x3F));
    }
    return offset;
}

private static int encodeChar(char c, byte[] buffer) {
    int offset = 0;
    if (c < 0x80) {
        offset += 1;
    } else if (c < 0x800) {
        offset += 2;
    } else if (c < 0xD800 || c >= 0xE000) {
        offset += 3;
    } else {
        offset += 4;
    }
    return offset;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    try {
        if (str == null || session == null || lb == null) {
            throw new IllegalArgumentException("Arguments cannot be null");
        }
        final int len = str.length();
        int offset = 0;
        LinkedBuffer buffer = lb;
        while (offset < len) {
            int available = buffer.buffer.remaining();
            if (available == 0) {
                buffer = buffer.nextBuffer(session);
                available = buffer.buffer.remaining();
            }
            int writeLength = Math.min(available, len - offset);
            for (int i = 0; i < writeLength; i++) {
                char c = str.charAt(offset + i);
                if (c <= 0x7F) {
                    buffer.buffer.put((byte) c);
                } else if (c <= 0x7FF) {
                    buffer.buffer.put((byte) (0xC0 | (c >> 6)));
                    buffer.buffer.put((byte) (0x80 | (c & 0x3F)));
                } else {
                    buffer.buffer.put((byte) (0xE0 | (c >> 12)));
                    buffer.buffer.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                    buffer.buffer.put((byte) (0x80 | (c & 0x3F)));
                }
            }
            offset += writeLength;
        }
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Failed to write UTF8 string to LinkedBuffer", e);
    }
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        final int len = str.length();
        int index = 0;
        LinkedBuffer currentBuffer = lb;
        while (index < len) {
            final int remaining = currentBuffer.limit() - currentBuffer.offset();
            int i = index;
            for (; i < len && i - index < remaining; i++) {
                final char c = str.charAt(i);
                if (c < 0x80) {
                    currentBuffer.buffer[currentBuffer.offset++] = (byte) c;
                } else if (c < 0x800) {
                    currentBuffer.buffer[currentBuffer.offset++] = (byte) (0xc0 | (c >> 6));
                    currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | (c & 0x3f));
                } else if (c < 0xd800 || c >= 0xe000) {
                    currentBuffer.buffer[currentBuffer.offset++] = (byte) (0xe0 | (c >> 12));
                    currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | ((c & 0xfc0) >> 6));
                    currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | (c & 0x3f));
                } else {
                    if (i + 1 >= len) throw new IllegalStateException("Invalid UTF-16 sequence");
                    char low = str.charAt(i + 1);
                    if (c < 0xdc00 || c >= 0xdc00 || low < 0xdc00 || low >= 0xe000) throw new IllegalStateException("Invalid UTF-16 surrogate pair");
                    int cp = (c << 10) + low + (0x10000 - (0xd800 << 10) - 0xdc00);
                    currentBuffer.buffer[currentBuffer.offset++] = (byte) (0xf0 | (cp >> 18));
                    currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | ((cp & 0x3f000) >> 12));
                    currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | ((cp & 0xfc0) >> 6));
                    currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | (cp & 0x3f));
                    i++; // Skip the next char as it is part of the surrogate pair
                }
            }
            index = i;
            if (index < len) {
                currentBuffer = currentBuffer.nextBuffer(session);
                if (currentBuffer == null) {
                    throw new IllegalStateException("Out of space in LinkedBuffer chain");
                }
            }
        }
        return currentBuffer;
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF-8 to LinkedBuffer", e);
    }
}

