public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props cannot be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        throw new NoSuchElementException("Key not found in properties: " + key);
    }

    // Simple variable substitution example: ${variable} -> props.getProperty("variable")
    StringBuilder substitutedValue = new StringBuilder();
    int length = value.length();
    for (int i = 0; i < length; i++) {
        if (value.charAt(i) == '$' && i + 1 < length && value.charAt(i + 1) == '{') {
            int closingIndex = value.indexOf('}', i + 2);
            if (closingIndex != -1) {
                String varName = value.substring(i + 2, closingIndex);
                String varValue = props.getProperty(varName);
                if (varValue != null) {
                    substitutedValue.append(varValue);
                } else {
                    throw new NoSuchElementException("Variable not found in properties: " + varName);
                }
                i = closingIndex; // Skip to the end of the variable
            } else {
                substitutedValue.append(value.charAt(i));
            }
        } else {
            substitutedValue.append(value.charAt(i));
        }
    }

    return substitutedValue.toString();
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props must not be null");
    }
    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("Key not found in properties");
    }
    return value.replaceAll("\\$\\{([^}]*)\\}", (match) -> {
        String varName = match.group(1);
        String varValue = props.getProperty(varName);
        return varValue != null ? varValue : match.group();
    });
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props cannot be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null; // or throw an exception if not found is an error case
    }

    // Simple variable substitution example: ${var} -> value of var from props
    return value.replaceAll("\\$\\{(.*?)\\}", match -> {
        String varName = match.group(1);
        String varValue = props.getProperty(varName);
        return varValue != null ? varValue : match.group(0); // keep original if not found
    });
}

public static String findAndSubst(String key, Properties props){
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props must not be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    // Simple variable substitution logic
    // This example assumes variables are in the form of ${var}
    StringBuilder result = new StringBuilder();
    Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
    Matcher matcher = pattern.matcher(value);
    int lastEnd = 0;
    while (matcher.find()) {
        result.append(value, lastEnd, matcher.start());
        String varName = matcher.group(1);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            result.append(varValue);
        } else {
            result.append(matcher.group(0)); // Keep the original ${var} if not found
        }
        lastEnd = matcher.end();
    }
    result.append(value.substring(lastEnd));

    return result.toString();
}

public static String findAndSubst(String key, Properties props){
    if (key == null || props == null) {
