private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        if (descriptor.charAt(0) == '(') { // Method descriptor
            int i = 1;
            while (descriptor.charAt(i) != ')') {
                i = popType(descriptor, i);
            }
        } else { // Field descriptor
            popType(descriptor, 0);
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B': case 'C': case 'I': case 'S': case 'Z':
            // These are single-word types
            return index + 1;
        case 'F':
            // Float is also a single-word type
            return index + 1;
        case 'D':
        case 'J':
            // Double and long are double-word types
            return index + 1;
        case 'L':
            // Object type
            return descriptor.indexOf(';', index) + 1;
        case '[':
            // Array type, skip to the next type descriptor
            return popType(descriptor, index + 1);
        default:
            throw new IllegalArgumentException("Unknown type character: " + descriptor.charAt(index));
    }
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    // Assuming the output frame stack is a list or array of types, for demonstration let's use a list
    // java.util.List<String> outputFrameStack = ...; // This should be defined somewhere in the class

    int pos = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, find the argument types
        pos = 1;
        while (descriptor.charAt(pos) != ')') {
            pos = popType(descriptor, pos);
        }
        pos++; // skip the ')'
    }
    // If descriptor is not a method, treat it as a single type
    popType(descriptor, pos);
}

private int popType(final String descriptor, int pos) {
    // java.util.List<String> outputFrameStack = ...; // This should be defined somewhere in the class

    char c = descriptor.charAt(pos);
    switch (c) {
        case 'B':
        case 'C':
        case 'I':
        case 'S':
        case 'Z':
            // These all represent 1-word data types
            // outputFrameStack.remove(outputFrameStack.size() - 1);
            pos++;
            break;
        case 'D':
        case 'J':
            // These represent 2-word data types
            // outputFrameStack.remove(outputFrameStack.size() - 1);
            // outputFrameStack.remove(outputFrameStack.size() - 1);
            pos++;
            break;
        case 'L':
        case '[':
            // These represent reference types (object references or arrays)
            // outputFrameStack.remove(outputFrameStack.size() - 1);
            pos = descriptor.indexOf(';', pos) + 1;
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    return pos;
