private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    // Assuming the output frame stack is a stack of types, represented as a Stack<String> for this example
    // and that the method descriptor format is similar to Java bytecode method descriptors
    Stack<String> outputFrameStack = new Stack<>();

    if (descriptor.startsWith("(")) {
        // It's a method descriptor, extract argument types
        int endIndex = descriptor.indexOf(')');
        if (endIndex == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String argsDescriptor = descriptor.substring(1, endIndex);
        int i = 0;
        while (i < argsDescriptor.length()) {
            char c = argsDescriptor.charAt(i);
            switch (c) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'S': // short
                case 'Z': // boolean
                    outputFrameStack.pop();
                    i++;
                    break;
                case 'J': // long
                    outputFrameStack.pop(); // long and double take two slots in the frame
                    outputFrameStack.pop();
                    i++;
                    break;
                case 'L': // reference
                case '[': // array reference
                    int semicolonIndex = argsDescriptor.indexOf(';', i);
                    if (c == 'L' && semicolonIndex == -1) {
                        throw new IllegalArgumentException("Invalid class descriptor: missing ';'");
                    }
                    outputFrameStack.pop();
                    i = semicolonIndex == -1 ? (argsDescriptor.length()) : (semicolonIndex + 1);
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type descriptor: " + c);
            }
        }
