                case 'D':
                case 'J':
                    // These are double-slot types
                    popDoubleSlotType();
                    i++;
                    break;
                case 'L':
                case '[':
                    // These are reference types
                    int semicolonIndex = argsDescriptor.indexOf(';', i);
                    if (semicolonIndex == -1) {
                        throw new IllegalArgumentException("Invalid descriptor for reference type");
                    }
                    popReferenceType();
                    i = semicolonIndex + 1;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid character in descriptor: " + c);
            }
        }
    } else {
        // Handle field descriptors
        switch (descriptor.charAt(0)) {
            case 'B':
