    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        // Check if the descriptor is a method descriptor
        if (descriptor.charAt(0) == '(') {
            // Find the closing parenthesis
            int endOfArgumentTypes = descriptor.indexOf(')');
            if (endOfArgumentTypes == -1) {
                throw new IllegalArgumentException("Invalid method descriptor format");
            }

            // Extract the argument types
            String argumentTypes = descriptor.substring(1, endOfArgumentTypes);

            int index = 0;
            while (index < argumentTypes.length()) {
                char type = argumentTypes.charAt(index);
                switch (type) {
                    case 'B':
                    case 'C':
                    case 'F':
                    case 'I':
