                    case 'L':
                    case '[':
                        popFrame(); // Pop one frame for these types
                        break;
                    case 'D':
                    case 'J':
                        popFrame(); // Pop one frame
                        popFrame(); // Pop another frame for double and long
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type character in descriptor: " + type);
                }

                // Move to the next type character
                index++;
                if (type == 'L') {
                    // Skip the class name part
                    while (index < argumentTypes.length() && argumentTypes.charAt(index) != ';') {
                        index++;
                    }
                }
            }
        } else {
            // Handle field type descriptor
            switch (descriptor.charAt(0)) {
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                case 'L':
                case '[':
                    popFrame();
                    break;
                case 'D':
                case 'J':
                    popFrame();
                    popFrame();
                    break;
                default:
                    throw new IllegalArgumentException("Invalid field type descriptor: " + descriptor);
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    } catch (Exception e) {
        throw new RuntimeException("An error occurred while popping frames", e);
    }
}

