        while (bytesRead != -1) {
            // If the buffer is full but there's more data, create a new, larger buffer
            if (bytesRead < buffer.length && in.available() > 0) {
                byte[] newBuffer = new byte[buffer.length + in.available()];
                System.arraycopy(buffer, 0, newBuffer, 0, bytesRead);
                bytesRead += in.read(newBuffer, bytesRead, newBuffer.length - bytesRead);
                buffer = newBuffer;
            } else {
                break;
            }
        }
        this.buffer = buffer;
        this.position = 0;
    } finally {
        in.close();
    }
}

