public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            if (i + 1 >= length) {
                throw new Exception("Invalid escape sequence at the end of the string.");
            }
            char nextChar = str.charAt(++i);
            switch (nextChar) {
                case 'n':
                    output.append('\n');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'b':
                    output.append('\b');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case 'a':
                    output.append('\u0007');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case '"':
                    output.append('"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case 'u': // Unicode escape
                    if (i + 4 >= length) {
                        throw new Exception("Invalid Unicode escape sequence.");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int unicode = Integer.parseInt(hex, 16);
                        output.append((char) unicode);
                        i += 4;
                    } catch (NumberFormatException e) {
                        throw new Exception("Malformed Unicode escape sequence: \\u" + hex);
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
            }
        } else {
            output.append(currentChar);
        }
    }
    return output.toString();
}

