protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        throw new IllegalArgumentException("Tour cannot be empty");
    }

    Map<V, List<E>> adjacencyMap = new HashMap<>();
    for (E edge : graph.edgeSet()) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        adjacencyMap.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        adjacencyMap.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    List<E> pathEdges = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    V currentVertex = startVertex;

    try {
        while (!visitedEdges.containsAll(edgeList)) {
            E nextEdge = null;
            for (E edge : adjacencyMap.get(currentVertex)) {
                if (edgeList.contains(edge) && !visitedEdges.contains(edge)) {
                    nextEdge = edge;
                    break;
                }
            }
            if (nextEdge == null) {
                throw new IllegalStateException("Cannot form a valid path with the given edges");
            }
            pathEdges.add(nextEdge);
            visitedEdges.add(nextEdge);
            currentVertex = graph.getEdgeSource(nextEdge).equals(currentVertex) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        }
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid tour or graph structure", e);
    }

    return new GraphPathImpl<>(graph, startVertex, currentVertex, pathEdges, 0);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();

    if (edgeList.isEmpty()) {
        return graph.getPathFactory().createPath(vertexList);
    }

    Map<V, List<E>> vertexOutEdges = new HashMap<>();
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        vertexOutEdges.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        vertexOutEdges.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    V startVertex = findStartVertex(vertexOutEdges, edgeList);
    if (startVertex == null) {
        throw new IllegalArgumentException("Invalid tour: cannot find a start vertex");
    }

    buildPath(startVertex, vertexOutEdges, edgeList, vertexList);

    return graph.getPathFactory().createPath(vertexList);
}

private V findStartVertex(Map<V, List<E>> vertexOutEdges, List<E> edgeList) {
    for (Map.Entry<V, List<E>> entry : vertexOutEdges.entrySet()) {
        V vertex = entry.getKey();
        int outDegree = entry.getValue().size();
        int inDegree = 0;

        for (E edge : edgeList) {
            if (graph.getEdgeTarget(edge).equals(vertex)) {
                inDegree++;
            }
        }

        if (outDegree - inDegree == 1) {
            return vertex;
        }
    }

    return edgeList.get(0) != null ? graph.getEdgeSource(edgeList.get(0)) : null;
}

private void buildPath(V currentVertex, Map<V, List<E>> vertexOutEdges, List<E> edgeList, List<V> vertexList) {
    List<E> edges = vertexOutEdges.get(currentVertex);
    if (edges != null) {
        for (E edge : new ArrayList<>(edges)) {
            V targetVertex = graph.getEdgeTarget(edge);
            edges.remove(edge);
            buildPath(targetVertex, vertexOutEdges, edgeList, vertexList);
        }
    }
    vertexList.add(0, currentVertex);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, 0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = null;
    GraphPathImpl.Builder<V, E> pathBuilder = new GraphPathImpl.Builder<>(graph);

    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (startVertex == null) {
            startVertex = source;
        } else if (!pathBuilder.getLastVertex().equals(source)) {
            throw new IllegalArgumentException("Edges do not form a continuous path");
        }

        pathBuilder.addVertex(target);
        pathBuilder.addEdge(edge);
    }

    if (!pathBuilder.getLastVertex().equals(startVertex)) {
        throw new IllegalArgumentException("The tour is not a cycle");
    }

    return pathBuilder.build();
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (vertexList.get(vertexList.size() - 1).equals(source)) {
            vertexList.add(target);
        } else if (vertexList.get(vertexList.size() - 1).equals(target)) {
            vertexList.add(source);
        } else {
            throw new IllegalArgumentException("Edges do not form a valid path");
        }
    }

    double weight = edgeList.stream().mapToDouble(graph::getEdgeWeight).sum();
    return new GraphPathImpl<>(graph, startVertex, vertexList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        throw new IllegalArgumentException("Tour must contain at least one edge");
    }

    V startVertex = null;
    List<V> vertexList = new ArrayList<>();

    for (E edge : edgeList) {
        if (startVertex == null) {
            startVertex = graph.getEdgeSource(edge);
            vertexList.add(startVertex);
        }
        V targetVertex = graph.getEdgeTarget(edge);
        if (!vertexList.get(vertexList.size() - 1).equals(graph.getEdgeSource(edge))) {
            throw new IllegalArgumentException("Edges are not forming a valid path");
        }
        vertexList.add(targetVertex);
    }

    if (!vertexList.get(0).equals(vertexList.get(vertexList.size() - 1))) {
        throw new IllegalArgumentException("Path is not a closed tour");
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList, edgeList, 0);
}

