private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    // Assuming DOT escape sequences are like "\e" for "e", replace them accordingly
    // Common escape sequences in DOT: \\, \", \n, \l, \r, \t, \b, \f, \/
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length()) {
                i++;
                char nextChar = input.charAt(i);
                switch (nextChar) {
                    case '\\': result.append('\\'); break;
                    case '"': result.append('"'); break;
                    case 'n': result.append('\n'); break;
                    case 'l': result.append('\n'); break; // \l is line break in DOT
                    case 'r': result.append('\r'); break;
                    case 't': result.append('\t'); break;
                    case 'b': result.append('\b'); break;
                    case 'f': result.append('\f'); break;
                    case '/': result.append('/'); break;
                    default: result.append(nextChar); break; // Unknown escape, keep as is
                }
            }
        } else {
            result.append(c);
        }
        i++;
    }
    return result.toString();
}

