    if (bounds == null) {
        throw new IllegalArgumentException("Input list cannot be null");
    }

    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    int currentSuffixSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        int value = bounds.get(i);
        if (value < 0) {
            throw new IllegalArgumentException("List elements cannot be negative");
        }
        currentSuffixSum += value;
        suffixSum.add(currentSuffixSum);
        totalSum += value;
    }

    Collections.reverse(suffixSum);
    return new Pair<>(suffixSum, totalSum);
}

