public void abbreviate(final int nameStart, final StringBuffer buf) {
    try {
        if (buf == null) {
            throw new IllegalArgumentException("Buffer cannot be null");
        }
        if (nameStart < 0) {
            throw new IllegalArgumentException("Name start index cannot be negative");
        }
        String name = buf.substring(nameStart);
        if (name.length() > 3) {
            buf.delete(nameStart, buf.length());
            buf.append(name.charAt(0)).append(name.charAt(1)).append('.').append(name.charAt(name.length() - 1));
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid name start index", e);
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    try {
        if (buf == null) {
            throw new IllegalArgumentException("Buffer cannot be null");
        }
        if (nameStart < 0 || nameStart >= buf.length()) {
            throw new IllegalArgumentException("nameStart is out of bounds");
        }
        String name = buf.substring(nameStart);
        String[] parts = name.split("\\s+");
        if (parts.length > 1) {
            StringBuilder abbreviation = new StringBuilder();
            for (String part : parts) {
                if (part.length() > 0) {
                    abbreviation.append(part.charAt(0)).append('.');
                }
            }
            buf.replace(nameStart, buf.length(), abbreviation.toString());
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

