    }

    // Normalize the paths to use "/". This is more consistent with Java's standard file path handling.
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Use a stack to handle the path segments efficiently.
    Deque<String> pathStack = new ArrayDeque<>();
    for (String segment : path.split("/")) {
        if (segment.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop();
            }
        } else if (!segment.isEmpty() && !segment.equals(".")) {
            pathStack.push(segment);
        }
