            if (!pathStack.isEmpty()) {
                pathStack.pop();
            }
        } else if (!segment.isEmpty() && !segment.equals(".")) {
            pathStack.push(segment);
        }
    }

    // Reconstruct the path from the stack
    StringBuilder result = new StringBuilder();
    while (!pathStack.isEmpty()) {
        if (result.length() > 0) {
            result.insert(0, "/");
        }
        result.insert(0, pathStack.pop());
    }

    // Ensure that the path starts with a leading slash if the original path started with it.
    if (path.startsWith("/") && result.length() > 0 && !result.toString().startsWith("/")) {
